import pandas as pd
import numpy as np
import json

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/cnt_batches.xlsx"

# Read the Raw sheet
df_raw = pd.read_excel(DATA_FILE, sheet_name="Raw")

# Extract data columns
temp = df_raw["Temperature (°C)"].values
weight = df_raw["Weight (%)"].values
deriv_weight = df_raw["Deriv. Weight (%/°C)"].values

# Prepare series data for ECharts
# We need to pair x and y values for scatter/line charts in ECharts format [[x1, y1], [x2, y2], ...]
